(()=>{var o={dialog:document.querySelector("dialog"),dialogDiv:document.querySelector("dialog div"),dialogButton:document.querySelector("dialog button")};o.dialog&&o.dialogButton?.addEventListener("click",()=>o.dialog?.close());window.dialog=(d,i=[])=>{o.dialog.className="",Array.isArray(i)&&i.length>0&&o.dialog?.classList.add(...i),o.dialogDiv.innerHTML=d,o.dialog?.showModal()};})();
